/**
 * Keyed-children diffing, as pure data.
 *
 * diffChildren(oldKeys, newKeys) returns a minimal-ish operation list:
 *   {type: 'remove', key}
 *   {type: 'insert', key, beforeKey: string | null}
 *   {type: 'move',   key, beforeKey: string | null}
 *
 * `beforeKey` is the key the node should be placed before; `null` means
 * "append at the end". Ops are ordered so that applying them sequentially
 * is always valid: all removes come first, then inserts/moves are emitted
 * scanning newKeys right-to-left, so every anchor (beforeKey) either never
 * moves (it's part of the LIS) or has already been placed by an earlier op.
 *
 * Moves are minimized with a longest-increasing-subsequence (LIS) over the
 * old indices of surviving keys: keys whose old indices form the LIS keep
 * their relative order and are never moved — only out-of-place nodes move,
 * like modern virtual-DOM frameworks (Vue, Inferno, React-reconciler forks).
 */

/** Assert input is a duplicate-free array of primitive keys. */
function assertValid(keys, label) {
  if (!Array.isArray(keys)) {
    throw new TypeError(`${label} must be an array`);
  }
  const seen = new Set();
  for (const key of keys) {
    if (typeof key !== 'string' && typeof key !== 'number') {
      throw new TypeError(`${label} keys must be strings or numbers`);
    }
    if (seen.has(key)) {
      throw new Error(`${label} contains duplicate key: ${String(key)}`);
    }
    seen.add(key);
  }
}

/**
 * Longest strictly-increasing subsequence over `seq` (array of numbers).
 * Returns a Set of the elements (by value) that belong to one LIS.
 * O(n log n), patience sorting with parent pointers.
 */
function lisMembers(seq) {
  const n = seq.length;
  if (n === 0) return new Set();
  const tails = []; // tails[i] = index in seq of smallest tail of LIS of length i+1
  const prev = new Array(n).fill(-1);
  for (let i = 0; i < n; i++) {
    const x = seq[i];
    // binary search for first tail whose value >= x (strictly increasing)
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (seq[tails[mid]] < x) lo = mid + 1;
      else hi = mid;
    }
    if (lo > 0) prev[i] = tails[lo - 1];
    if (lo === tails.length) tails.push(i);
    else tails[lo] = i;
  }
  const members = new Set();
  for (let i = tails[tails.length - 1]; i !== -1; i = prev[i]) {
    members.add(seq[i]);
  }
  return members;
}

/**
 * Compute the operation list transforming oldKeys into newKeys.
 * Throws on duplicate keys or non-array input.
 */
export function diffChildren(oldKeys, newKeys) {
  assertValid(oldKeys, 'oldKeys');
  assertValid(newKeys, 'newKeys');

  const oldIndex = new Map(oldKeys.map((key, i) => [key, i]));
  const newSet = new Set(newKeys);

  // 1. Removals: present in old but not in new.
  const ops = [];
  for (const key of oldKeys) {
    if (!newSet.has(key)) ops.push({ type: 'remove', key });
  }

  // 2. Survivors' old indices, in new order. LIS members stay put.
  const survivingIndices = [];
  for (const key of newKeys) {
    const idx = oldIndex.get(key);
    if (idx !== undefined) survivingIndices.push(idx);
  }
  const stable = lisMembers(survivingIndices);

  // 3. Inserts & moves: scan new order right-to-left so each op's anchor
  //    (beforeKey) is guaranteed to already be in place when applied.
  let si = 0;
  const upserts = [];
  for (let j = newKeys.length - 1; j >= 0; j--) {
    const key = newKeys[j];
    const beforeKey = j + 1 < newKeys.length ? newKeys[j + 1] : null;
    const idx = oldIndex.get(key);
    if (idx === undefined) {
      upserts.unshift({ type: 'insert', key, beforeKey });
    } else if (!stable.has(idx)) {
      upserts.unshift({ type: 'move', key, beforeKey });
    }
    si++;
  }

  return [...ops, ...upserts];
}

/**
 * Apply an op list from diffChildren to oldKeys; returns exactly newKeys
 * when the ops were generated by diffChildren(oldKeys, newKeys).
 */
export function applyOps(oldKeys, ops) {
  const keys = [...oldKeys];
  const indexOf = (key) => keys.indexOf(key);

  for (const op of ops) {
    if (op.type === 'remove') {
      const at = indexOf(op.key);
      if (at === -1) throw new Error(`applyOps: cannot remove missing key ${op.key}`);
      keys.splice(at, 1);
    } else if (op.type === 'insert') {
      const at = op.beforeKey == null ? keys.length : indexOf(op.beforeKey);
      if (op.beforeKey != null && at === -1) {
        throw new Error(`applyOps: anchor ${op.beforeKey} not found`);
      }
      keys.splice(at, 0, op.key);
    } else if (op.type === 'move') {
      const from = indexOf(op.key);
      if (from === -1) throw new Error(`applyOps: cannot move missing key ${op.key}`);
      keys.splice(from, 1);
      const at = op.beforeKey == null ? keys.length : indexOf(op.beforeKey);
      if (op.beforeKey != null && at === -1) {
        throw new Error(`applyOps: anchor ${op.beforeKey} not found`);
      }
      keys.splice(at, 0, op.key);
    } else {
      throw new Error(`applyOps: unknown op type ${op.type}`);
    }
  }
  return keys;
}

