import { describe, it, expect } from 'vitest';
import { diffChildren, applyOps } from '../src/diff.js';

/** Fisher–Yates shuffle (deterministic PRNG for reproducibility). */
function mulberry32(seed) {
  return function () {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

describe('diffChildren', () => {
  it('handles the trivial cases', () => {
    expect(diffChildren([], [])).toEqual([]);
    expect(diffChildren(['a'], ['a'])).toEqual([]);
    // identical order -> no ops at all
    expect(diffChildren(['a', 'b', 'c'], ['a', 'b', 'c'])).toEqual([]);
    // pure append
    expect(applyOps(['a'], diffChildren(['a'], ['a', 'b']))).toEqual(['a', 'b']);
  });

  it('known case: single out-of-place node produces exactly one move', () => {
    const ops = diffChildren(['a', 'b', 'c', 'd'], ['d', 'a', 'b', 'c']);
    expect(ops.filter((o) => o.type === 'move').length).toBe(1);
    expect(ops.filter((o) => o.type === 'remove')).toEqual([]);
    expect(applyOps(['a', 'b', 'c', 'd'], ops)).toEqual(['d', 'a', 'b', 'c']);
  });

  it('property loop: 300 random permutation / insert / remove mixes round-trip', () => {
    const rand = mulberry32(1337);
    for (let trial = 0; trial < 300; trial++) {
      const nOld = 1 + Math.floor(rand() * 12);
      const pool = Array.from({ length: nOld + 6 }, (_, i) => `k${i}`);
      // draw a duplicate-free old list
      const shuffled = [...pool];
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
      }
      const oldKeys = shuffled.slice(0, nOld);

      // build newKeys: permute survivors, drop some, insert some fresh keys
      const survivors = [...oldKeys];
      for (let i = survivors.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [survivors[i], survivors[j]] = [survivors[j], survivors[i]];
      }
      const keepCount = Math.max(0, survivors.length - Math.floor(rand() * 4));
      const kept = survivors.slice(0, keepCount);
      const removed = survivors.slice(keepCount);
      const freshPool = ['x1', 'x2', 'x3', 'x4'].filter((k) => !oldKeys.includes(k) && !removed.includes(k));
      const freshCount = Math.floor(rand() * (freshPool.length + 1));
      const fresh = freshPool.sort(() => rand() - 0.5).slice(0, freshCount);

      const newKeys = [...kept];
      for (const k of fresh) {
        newKeys.splice(Math.floor(rand() * (newKeys.length + 1)), 0, k);
      }

      const ops = diffChildren(oldKeys, newKeys);
      const result = applyOps(oldKeys, ops);
      try {
        expect(result).toEqual(newKeys);
      } catch (err) {
        throw new Error(
          `trial ${trial} failed\nold=${JSON.stringify(oldKeys)}\nnew=${JSON.stringify(newKeys)}\nresult=${JSON.stringify(result)}\nops=${JSON.stringify(ops)}`
        );
      }
    }
  });

  it('zero moves for a pure insertion', () => {
    const ops = diffChildren(['c', 'e', 'g'], ['a', 'b', 'c', 'e', 'f', 'g', 'h']);
    expect(ops.every((o) => o.type !== 'move')).toBe(true);
    expect(ops.length).toBe(4);
    expect(applyOps(['c', 'e', 'g'], ops)).toEqual(['a', 'b', 'c', 'e', 'f', 'g', 'h']);
  });

  it('zero moves for a pure removal', () => {
    const ops = diffChildren(['a', 'b', 'c', 'd', 'e', 'f'], ['b', 'd', 'f']);
    expect(ops.every((o) => o.type !== 'move' && o.type !== 'insert')).toBe(true);
    expect(ops.map((o) => o.key).sort()).toEqual(['a', 'c', 'e']);
    expect(applyOps(['a', 'b', 'c', 'd', 'e', 'f'], ops)).toEqual(['b', 'd', 'f']);
  });

  it('worst case full reversal needs at most length-1 moves (and is exact)', () => {
    for (const n of [2, 5, 10, 50]) {
      const keys = Array.from({ length: n }, (_, i) => `r${i}`);
      const reversed = [...keys].reverse();
      const ops = diffChildren(keys, reversed);
      const moves = ops.filter((o) => o.type === 'move').length;
      expect(moves).toBeLessThanOrEqual(n - 1);
      expect(moves).toBe(n - 1); // LIS of a reversal is length 1
      expect(applyOps(keys, ops)).toEqual(reversed);
    }
  });

  it('throws on duplicate keys in either input', () => {
    expect(() => diffChildren(['a', 'a'], ['a'])).toThrow(/duplicate/i);
    expect(() => diffChildren(['a'], ['b', 'b'])).toThrow(/duplicate/i);
    expect(() => diffChildren('nope', ['a'])).toThrow(TypeError);
    expect(() => applyOps(['a', 'a'], [])).toThrow(/duplicate/i);
  });
});

